use num_bigint::BigUint;
use xone_domain::Amount;
use xone_protocol_math::managed_v2_aum::preview_aum;
fn a(s: &str) -> Amount {
    s.parse().unwrap()
}
#[test]
fn published_original_vault_nonzero_aum_and_protocol_mint_match_observed_units() {
    // Original 20230411 pool, real Vault 30-day collection; independent Node
    // evidence is retained by the native reference, not generated by this kernel.
    let q = preview_aum(
        &a("22973967099940240610944"),
        1769817600,
        1767225600,
        &a("10000000000000000"),
        &a("300000000000000000"),
    )
    .unwrap();
    assert_eq!(q.total_bpt, a("19073447156446858124"));
    assert_eq!(q.protocol_bpt, a("5722034146934057438"));
    assert_eq!(q.manager_bpt, a("13351413009512800686"));
    assert_eq!(q.actual_supply, a("22993040547096687469068"));
}
#[test]
fn source_rounding_order_and_protocol_ceil_favor_lp_then_protocol() {
    let q = preview_aum(
        &a("1"),
        31_536_001,
        1,
        &a("950000000000000000"),
        &a("10000000000000000"),
    )
    .unwrap();
    assert_eq!(q.total_bpt, a("19"));
    assert_eq!(q.protocol_bpt, a("1"));
    assert_eq!(q.manager_bpt, a("18"));
    assert_eq!(q.actual_supply, a("20"));
    let dust = preview_aum(
        &a("1"),
        31_536_001,
        1,
        &a("10000000000000000"),
        &a("300000000000000000"),
    )
    .unwrap();
    assert_eq!(dust.total_bpt, Amount::zero());
    for share in ["0", "1000000000000000000"] {
        let q = preview_aum(&a("1"), 31_536_001, 1, &a("950000000000000000"), &a(share)).unwrap();
        assert_eq!(&q.protocol_bpt.0 + &q.manager_bpt.0, q.total_bpt.0);
    }
}
#[test]
fn zero_fee_or_nonpositive_elapsed_returns_before_overflowing_annual_math() {
    let max = Amount((BigUint::from(1u8) << 256usize) - BigUint::from(1u8));
    for (time, last, fee) in [
        (1, 1, "950000000000000000"),
        (0, 1, "950000000000000000"),
        (u64::MAX, 1, "0"),
    ] {
        let q = preview_aum(&max, time, last, &a(fee), &a("300000000000000000")).unwrap();
        assert_eq!(q.total_bpt, Amount::zero());
        assert_eq!(q.actual_supply, max);
    }
}
#[test]
fn invalid_percentages_and_each_safe_math_overflow_are_rejected() {
    let max = Amount((BigUint::from(1u8) << 256usize) - BigUint::from(1u8));
    for (supply, time, fee, share) in [
        (&max, 2, "10000000000000000", "0"),
        (&max, u64::MAX, "1", "0"),
        (&max, 31_536_001, "1", "0"),
    ] {
        assert!(preview_aum(supply, time, 1, &a(fee), &a(share)).is_err());
    }
    assert!(preview_aum(&a("1"), 2, 1, &a("950000000000000001"), &a("0")).is_err());
    assert!(preview_aum(&a("1"), 2, 1, &a("1"), &a("1000000000000000001")).is_err());
    let wide = Amount(BigUint::from(1u8) << 256usize);
    assert!(preview_aum(&wide, 1, 1, &a("0"), &a("0")).is_err());
}

fn collection_input() -> xone_protocol_math::managed_v2_aum::AumCollectionInput {
    use xone_protocol_math::managed_v2_aum::AumCollectionInput;
    AumCollectionInput {
        total_supply: a("2596148429267413814265248164610048"),
        vault_bpt_balance: a("2596148429244439847165307923999104"),
        manager_bpt_balance: Amount::zero(),
        protocol_bpt_balance: Amount::zero(),
        same_recipient: false,
        last_collection_timestamp: 1767225600,
        annual_fee: a("10000000000000000"),
        cached_protocol_share: a("300000000000000000"),
        paused: false,
        buffer_period_end: 1768000000,
        recovery_mode: false,
    }
}
#[test]
fn original_collection_updates_real_ledgers_and_keeps_actual_supply_continuous() {
    use xone_protocol_math::managed_v2_aum::collect_aum;
    let before = collection_input();
    let result = collect_aum(&before, 1769817600).unwrap();
    assert_eq!(
        result.next.total_supply,
        a("2596148429267432887712404611468172")
    );
    assert_eq!(result.next.protocol_bpt_balance, a("5722034146934057438"));
    assert_eq!(result.next.manager_bpt_balance, a("13351413009512800686"));
    assert_eq!(result.next.last_collection_timestamp, 1769817600);
    assert_eq!(result.next.vault_bpt_balance, before.vault_bpt_balance);
    assert_eq!(result.virtual_supply_after, a("22993040547096687469068"));
    assert_eq!(result.actual_supply_after, result.accrual.actual_supply);
    let repeated = collect_aum(&result.next, 1769817600).unwrap();
    assert_eq!(repeated.accrual.total_bpt, Amount::zero());
    assert_eq!(repeated.next, result.next);
}
#[test]
fn collection_alias_pause_recovery_and_uint32_write_boundary_follow_original() {
    use xone_protocol_math::managed_v2_aum::collect_aum;
    let mut input = collection_input();
    input.same_recipient = true;
    let r = collect_aum(&input, 1769817600).unwrap();
    assert_eq!(r.next.manager_bpt_balance, r.accrual.total_bpt);
    assert_eq!(r.next.protocol_bpt_balance, r.accrual.total_bpt);
    input.manager_bpt_balance = a("1");
    assert!(collect_aum(&input, 1769817600).is_err());
    input = collection_input();
    input.paused = true;
    input.buffer_period_end = 1769817601;
    assert!(collect_aum(&input, 1769817600).is_err());
    assert!(
        collect_aum(&input, 1769817601).is_err(),
        "original buffer end is inclusive while paused"
    );
    assert!(collect_aum(&input, 1769817602).is_ok());
    input = collection_input();
    input.recovery_mode = true;
    let r = collect_aum(&input, 1769817600).unwrap();
    assert_eq!(r.accrual.total_bpt, Amount::zero());
    assert_eq!(r.next.total_supply, input.total_supply);
    assert_eq!(r.next.last_collection_timestamp, 1769817600);
    assert!(collect_aum(&input, u64::from(u32::MAX) + 1).is_err());
    input = collection_input();
    input.annual_fee = Amount::zero();
    let r = collect_aum(&input, 1769817600).unwrap();
    assert_eq!(r.next.last_collection_timestamp, 1769817600);
    assert_eq!(r.accrual.total_bpt, Amount::zero());
}
#[test]
fn collection_rejects_uninitialized_vault_width_and_supply_accounting_corruption() {
    use xone_protocol_math::managed_v2_aum::collect_aum;
    for bad in 0..5 {
        let mut input = collection_input();
        match bad {
            0 => input.total_supply = input.vault_bpt_balance.clone(),
            1 => input.vault_bpt_balance = Amount(BigUint::from(1u8) << 112usize),
            2 => input.vault_bpt_balance = input.total_supply.clone(),
            3 => {
                input.manager_bpt_balance =
                    Amount(input.total_supply.0.clone() + BigUint::from(1u8))
            }
            _ => input.total_supply = Amount((BigUint::from(1u8) << 256usize) - BigUint::from(1u8)),
        };
        assert!(collect_aum(&input, 1769817600).is_err(), "bad={bad}");
    }
}

#[test]
fn actual_supply_view_does_not_run_the_later_collection_protocol_split() {
    use xone_protocol_math::managed_v2_aum::view_aum;
    // The source getActualSupply path only computes pending inflation. A large
    // valid view may succeed while the subsequent checked mulUp split reverts.
    let supply = Amount(BigUint::from(10u8).pow(57));
    let fee = a("950000000000000000");
    let share = a("300000000000000000");
    let time = 100u64 * 365 * 86400 + 1;
    let q = view_aum(&supply, time, 1, &fee).unwrap();
    assert_eq!(q.pending_bpt, Amount(&supply.0 * BigUint::from(1900u16)));
    assert_eq!(q.actual_supply, Amount(&supply.0 * BigUint::from(1901u16)));
    assert!(
        preview_aum(&supply, time, 1, &fee, &share).is_err(),
        "view success must not silently remove collection SafeMath limits"
    );
}

#[test]
fn annual_floor_precedes_elapsed_scaling_and_protocol_ceil_gets_the_dust() {
    // floor(1 * .4 / .6) = 0 before multiplying by two years. Combining
    // both divisions into one would incorrectly mint one unit instead.
    let q = preview_aum(
        &a("1"),
        2 * 31_536_000 + 1,
        1,
        &a("400000000000000000"),
        &a("300000000000000000"),
    )
    .unwrap();
    assert_eq!(q.total_bpt, Amount::zero());
    assert_eq!(q.actual_supply, a("1"));
    // floor(3 * .5 / .5) = 3, then half a year floors to one BPT.
    // ceil(1 * .3) gives that single unit to the protocol.
    let q = preview_aum(
        &a("3"),
        31_536_000 / 2 + 1,
        1,
        &a("500000000000000000"),
        &a("300000000000000000"),
    )
    .unwrap();
    assert_eq!(q.total_bpt, a("1"));
    assert_eq!(q.protocol_bpt, a("1"));
    assert_eq!(q.manager_bpt, Amount::zero());
    assert_eq!(q.actual_supply, a("4"));
}
